<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Reading } from '@element-plus/icons-vue'
import AgentSettings from '../components/AgentSettings.vue'
import { api, action, labels, waitTask } from '../api'
const apps=ref<any[]>([]),kbs=ref<any[]>([]),profiles=ref<any[]>([]),open=ref(false),editId=ref(''),busy=ref(false),preview=ref<any>()
const form=reactive<any>({}),capabilities=ref<any>({skills:[],defaults:{}})
async function load(){[apps.value,kbs.value,profiles.value,capabilities.value]=await Promise.all([api('/admin/apps'),api('/admin/knowledge-bases'),api('/admin/model-profiles'),api('/admin/agent-capabilities')])}
onMounted(()=>action(load))
function edit(app?:any){editId.value=app?.id||'';Object.assign(form,app?JSON.parse(JSON.stringify(app.draft)):{name:'',description:'',prompt:'你是一位严谨、耐心的课程学习助教。请依据当前课程资料回答问题。',model_profile_id:'',embedding_profile_id:'',kb_ids:[],features:['chat','quiz'],agent:{}});form.agent={...JSON.parse(JSON.stringify(capabilities.value.defaults)),...JSON.parse(JSON.stringify(app?.draft.agent||{})),enabled:app?(app.draft.agent?.enabled??false):true};open.value=true}
async function save(){busy.value=true;await action(async()=>{await api('/admin/apps'+(editId.value?'/'+editId.value:''),editId.value?'PUT':'POST',form);open.value=false;await load();ElMessage.success('草稿已保存，发布后对学生生效')});busy.value=false}
async function publish(id:string){busy.value=true;await action(async()=>{const task=await api('/admin/apps/'+id+'/publish','POST');ElMessage.info('正在测试模型并构建匹配的向量索引');await waitTask(task);await load();ElMessage.success('应用已发布')});busy.value=false}
async function remove(id:string){try{await ElMessageBox.confirm('删除后用户将无法进入此应用，历史记录会保留。','删除应用',{type:'warning'});await action(async()=>{await api('/admin/apps/'+id,'DELETE');await load()})}catch{}}
</script>
<template><section class="page"><div class="page-eyebrow">ADMINISTRATION / APPLICATIONS</div><div class="page-title"><div><h1>应用管理</h1><p class="muted">将知识、模型与学习任务，组合成一个应用。</p></div><el-button type="primary" @click="edit()">＋ 创建应用</el-button></div><div class="app-grid"><article v-for="a in apps" :key="a.id" class="app-card admin-card"><div class="card-top"><span class="app-symbol"><el-icon><Reading/></el-icon></span><el-tag :type="a.active?'success':'info'">{{a.active?'已发布':'未发布'}}</el-tag></div><h3>{{a.draft.name}}</h3><p>{{a.draft.description}}</p><div class="tags"><span v-for="f in a.draft.features" :key="f">{{labels[f]}}</span></div><p class="muted">{{a.draft.kb_ids.length}} 个知识库 · 配置版本 {{a.version}}</p><div class="card-actions"><el-button @click="edit(a)">编辑</el-button><el-button @click="preview=a">预览</el-button><router-link v-if="a.active" :to="{path:'/admin/review-plans',query:{app_id:a.id}}"><el-button>复习计划</el-button></router-link><el-button type="primary" :loading="busy" @click="publish(a.id)">发布</el-button><el-dropdown><el-button>更多</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="action(async()=>{await api('/admin/apps/'+a.id+'/unpublish','POST');await load()})">下架</el-dropdown-item><el-dropdown-item @click="remove(a.id)">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></article></div><el-empty v-if="!apps.length" description="创建第一个学习应用，将知识交给学生"/>
<el-drawer v-model="open" :title="editId?'编辑应用配置':'创建学习应用'" size="min(600px, 96vw)"><el-form label-position="top"><el-form-item label="应用名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="应用简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="生成模型"><el-select v-model="form.model_profile_id" placeholder="选择用于问答的模型" class="full-width"><el-option v-for="p in profiles.filter(p=>p.purpose==='generation')" :key="p.id" :label="p.name+' · '+p.model" :value="p.id"/></el-select></el-form-item><el-form-item label="Embedding 模型"><el-select v-model="form.embedding_profile_id" placeholder="选择本地或云端向量模型" class="full-width"><el-option v-for="p in profiles.filter(p=>p.purpose==='embedding')" :key="p.id" :label="p.name+' · '+p.dimension+' 维'" :value="p.id"/></el-select><p class="form-help">发布时为所选模型构建独立索引，构建成功前保持现有应用可用。</p></el-form-item><router-link class="text-link" to="/admin/models">管理模型或扫描本地服务 ↗</router-link><el-form-item label="绑定知识库" class="spaced"><el-select v-model="form.kb_ids" multiple class="full-width"><el-option v-for="k in kbs" :key="k.id" :value="k.id" :label="k.name+(k.current_release_id?'':'（未发布）')"/></el-select></el-form-item><el-form-item label="学习功能"><el-checkbox-group v-model="form.features"><el-checkbox v-for="f in ['chat','quiz']" :key="f" :value="f">{{labels[f]}}</el-checkbox></el-checkbox-group></el-form-item><AgentSettings v-if="form.agent" v-model="form.agent" :skills="capabilities.skills"/><el-form-item label="助教提示词"><el-input v-model="form.prompt" type="textarea" :rows="5"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></template></el-drawer>
<el-dialog :model-value="!!preview" title="应用配置预览" @close="preview=null"><template v-if="preview"><h2>{{preview.draft.name}}</h2><p>{{preview.draft.description}}</p><p>知识库：{{preview.draft.kb_ids.map((id:string)=>kbs.find(k=>k.id===id)?.name).join('、')}}</p><p>生成模型：{{profiles.find(p=>p.id===preview.draft.model_profile_id)?.name}}</p><p>向量模型：{{profiles.find(p=>p.id===preview.draft.embedding_profile_id)?.name}}</p><p>自主助教：{{preview.draft.agent?.enabled?'已启用':'未启用'}}<span v-if="preview.draft.agent?.enabled"> · 最多 {{preview.draft.agent.max_subagents}} 个子 agent</span></p><div class="quiet-note preserve">{{preview.draft.prompt}}</div><router-link v-if="preview.active" :to="'/apps/'+preview.id" class="text-link">打开当前已发布版本 ↗</router-link></template></el-dialog>
</section></template>
